1	/**
2	 * Foam banks along the stream (refs 03–10) + whirlpool rim foam.
3	 *  - berm: ONE continuous lumpy lather bank per side, swept along the course (custom shader:
4	 *    two-scale cellular soap bubbles with derivative bump lighting, lavender crevices, pores,
5	 *    faint iridescent rim). This is what makes the banks read as continuous foam, not cotton balls.
6	 *  - puffs: instanced bubble puffs sitting ON the berm crest (silhouette lumps), in ~40-unit chunks
7	 *    so only chunks near Benny are drawn; quality 'low' halves density and uses 20-tri puffs.
8	 *  - foam rings on the whirlpool rim and along its spiral bands (rotating with the swirl)
9	 *  - flank banks (05, wave 4): one CONTINUOUS cloud bank per side that continues the berm down both
10	 *    sides of the frame to Benny's level (ref 05: banks hugging BOTH edges y≈540–1300): a lather sheet
11	 *    (berm shader, 1 draw) + world-anchored instanced puffs (1 draw), fitted to the frame edges from
12	 *    the camera each frame. Replaces wave 3's floating "flank"/"wake" raft clumps, which read as round
13	 *    islands on open water. Fixed pools, no per-frame allocation.
14	 */
15	import * as THREE from 'three';
16	import { type Course, WORLD, funnelY } from '../world/course';
17	import { EDGE_LIFT, coreLateral } from './waterRibbon';
18	import { SPIRAL_C, FUNNEL_LIFT } from './whirlpool';
19	import { FRAG_FX_GLSL, FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
20	
21	/** c = (ambient occlusion 0..1, seed 0..1, tint -1..1) → instanceColor (see PUFF_VERT) */
22	interface Puff { p: THREE.Vector3; r: number; ao: number; tint: number; w5?: number }
23	
24	// ---------------------------------------------------------------------------------- berm profile
25	/** berm spans e ∈ [BERM_IN, BERM_OUT] units outward from the ribbon edge (negative = over the water) */
26	export const BERM_IN = -0.6;
27	export const BERM_OUT = 1.2;
28	const hash1 = (n: number) => { const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
29	const noise1 = (x: number) => { const i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f); return hash1(i) * (1 - u) + hash1(i + 1) * u; };
30	/** 0..1 lumpiness of the bank at (s, side) — CPU only, baked into the mesh and the puff placement */
31	export function bermLump(s: number, side: number): number {
32	  return 0.55 * noise1(s * 0.33 + side * 31.7) + 0.45 * noise1(s * 1.05 + side * 7.3);
33	}
34	/** CPU cellular "bubble dome" field (0..1) so the bank silhouette is a pile of round lumps */
35	export function bermDomes(s: number, e: number, side: number): number {
36	  const gs = s / 0.95, ge = e / 0.62 + side * 11.3;
37	  const i0 = Math.floor(gs), j0 = Math.floor(ge);
38	  let best = 0;
39	  for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
40	    const i = i0 + di, j = j0 + dj;
41	    const ox = hash1(i * 17.13 + j * 3.71), oy = hash1(i * 5.31 + j * 19.7 + 4.2);
42	    const r = 0.45 + 0.4 * hash1(i * 7.7 + j * 13.1 + 9.9);
43	    const dx = (i + ox - gs) / r, dy = (j + oy - ge) / r;
44	    best = Math.max(best, 1 - (dx * dx + dy * dy));
45	  }
46	  return Math.max(0, best);
47	}
48	
49	/** height (along course up) of the bank surface at e units outward from the edge */
50	export function bermHeight(e: number, hw: number, lump: number): number {
51	  const uIn = Math.max(0, (hw + BERM_IN) / hw);
52	  const hIn = EDGE_LIFT * uIn * uIn * uIn - 0.07;
53	  const ep = 0.08 + 0.22 * lump;
54	  const hp = EDGE_LIFT + 0.14 + 0.5 * lump;
55	  const hOut = -0.95;
56	  if (e <= ep) {
57	    const t = Math.min(1, Math.max(0, (e - BERM_IN) / (ep - BERM_IN)));
58	    return hIn + (hp - hIn) * (1 - (1 - t) * (1 - t));
59	  }
60	  const t = Math.min(1, (e - ep) / (BERM_OUT - ep));
61	  return hp + (hOut - hp) * t * t;
62	}
63	
64	/** full bank surface height incl. bubble domes (shared by the mesh and the puff placement) */
65	export function bermSurface(s: number, e: number, side: number, hw: number): number {
66	  const domeK = Math.min(1, Math.max(0, (e + 0.3) / 0.35)) * Math.min(1, Math.max(0, (BERM_OUT - 0.1 - e) / 0.4));
67	  return bermHeight(e, hw, bermLump(s, side)) + 0.2 * domeK * Math.sqrt(bermDomes(s, e, side));
68	}
69	
70	/**
71	 * wave 7: ref 05 soap colour ramp t = 0..1: blue-violet crevice -> blue -> periwinkle -> lavender-white -> white
72	 * top cap. Stops = the ref 05 rim foam at its 5/20/50/70/90th luminance percentiles ((107,101,234) (117,143,247)
73	 * (171,184,250) (216,212,251) (250,243,254)) inverted through the display pipeline (Neutral tone map x0.86 ->
74	 * sRGB -> grade sat 1.36 / contrast 1.15; qa/pilot05/wave6/foam/tools/pipe.py). Only t > 0.8 reaches white.
75	 * `soapT` = the shared view-space lighting (top-lit from the upper left, like the ref bubbles).
76	 */
77	const SOAP05_GLSL = /* glsl */ `
78	const vec3 SOAP_CREV = vec3(0.23, 0.22, 0.66);
79	vec3 soap05(float t) {
80	  t = clamp(t, 0.0, 1.0) * 5.0;
81	  vec3 c = mix(SOAP_CREV, vec3(0.26, 0.38, 0.84), clamp(t, 0.0, 1.0));
82	  c = mix(c, vec3(0.38, 0.54, 0.97), clamp(t - 1.0, 0.0, 1.0));
83	  c = mix(c, vec3(0.56, 0.63, 0.96), clamp(t - 2.0, 0.0, 1.0));
84	  c = mix(c, vec3(0.78, 0.79, 0.98), clamp(t - 3.0, 0.0, 1.0));
85	  return mix(c, vec3(1.05, 1.03, 1.08), clamp(t - 4.0, 0.0, 1.0));
86	}
87	float soapT(vec3 Nv) {
88	  vec3 Lv = normalize(vec3(-0.35, 0.8, 0.5));
89	  float wrap = clamp(dot(Nv, Lv) * 0.55 + 0.5, 0.0, 1.0);
90	  float up = clamp(Nv.y * 0.5 + 0.5, 0.0, 1.0);
91	  return smoothstep(0.1, 0.8, wrap * 0.6 + up * 0.4);
92	}
93	`;
94	
95	const BERM_VERT = /* glsl */ `
96	attribute vec3 aFoam;    // x = e (units outward from the stream edge), y = s, z = side (-1 / 1)
97	uniform float uTime;
98	varying vec3 vFoam;
99	varying vec3 vPosW;
100	varying vec3 vNormalW;
101	#include <fog_pars_vertex>
102	void main() {
103	  // gentle breathing of the lather (never at the water line)
104	  float k = smoothstep(-0.2, 0.3, aFoam.x);
105	  vec3 p = position + normal * (0.03 * k * sin(uTime * 1.6 + aFoam.y * 2.1 + aFoam.z * 3.0));
106	  vec4 wp = modelMatrix * vec4(p, 1.0);
107	  vPosW = wp.xyz;
108	  vNormalW = normalize(mat3(modelMatrix) * normal);
109	  vFoam = aFoam;
110	  vec4 mvPosition = viewMatrix * wp;
111	  gl_Position = projectionMatrix * mvPosition;
112	  #include <fog_vertex>
113	}
114	`;
115	
116	const BERM_FRAG = /* glsl */ `
117	uniform float uTime;
118	uniform vec2 uOutro;     // amount, chamber start s
119	uniform vec3 uLightDir;
120	uniform vec4 uSt05;      // wave 7: 05 soap shading weight ramps in s0..s1, out s2..s3 (= bermScale05)
121	varying vec3 vFoam;
122	varying vec3 vPosW;
123	varying vec3 vNormalW;
124	#include <fog_pars_fragment>
125	${NOISE_GLSL}
126	${FRAG_FX_GLSL}
127	${SOAP05_GLSL}
128	void main() {
129	  float s = vFoam.y;
130	  if (uOutro.x > 0.0 && s > uOutro.y - 2.0) {
131	    float n = vnoise(vec2(vFoam.x * 3.0, s * 0.35)) * 0.7 + 0.3;
132	    if (n < uOutro.x * 1.15) discard;
133	  }
134	  vec2 p = vec2(vFoam.x * vFoam.z * 1.1, s - uTime * 0.25);
135	  // detail fade with distance (cells per pixel)
136	  float fw = max(fwidth(p.x), fwidth(p.y));
137	  float k1 = 1.0 - smoothstep(0.12, 0.3, fw * 1.6);
138	  float k2 = 1.0 - smoothstep(0.12, 0.3, fw * 3.8);
139	  float c1 = mix(0.45, cells(p * 1.6), k1);
140	  #ifdef LOW_Q
141	  float c2 = c1;
142	  #else
143	  float c2 = mix(0.45, cells(p * 3.8 + 11.0), k2);
144	  #endif
145	  // bubble domes: bright cell centres, deep crevices between bubbles
146	  float bub = (1.0 - c1 * c1) * 0.6 + (1.0 - c2 * c2) * 0.4;
147	  vec3 N0 = normalize(vNormalW);
148	  if (!gl_FrontFacing) N0 = -N0;
149	  #ifdef LOW_Q
150	  vec3 N = N0;
151	  #else
152	  vec3 N = bumpNormal(vPosW, N0, bub * 0.1);
153	  #endif
154	  vec3 L = normalize(uLightDir);
155	  vec3 V = normalize(cameraPosition - vPosW);
156	  float diff = 0.55 + 0.45 * max(dot(N, L), 0.0);
157	  vec3 white = vec3(1.0, 1.0, 1.0);
158	  vec3 lav = vec3(0.7, 0.68, 0.98);
159	  vec3 col = mix(lav, white, 0.3 + 0.7 * clamp(N.y * 0.5 + 0.5, 0.0, 1.0)) * diff;
160	  col = mix(col, lav * 0.8, smoothstep(0.6, 0.95, c1) * 0.7 * k1);
161	  col = mix(col, lav * 0.9, smoothstep(0.65, 0.95, c2) * 0.4 * k2);
162	  // tiny pores (open bubbles)
163	  #ifndef LOW_Q
164	  vec2 pp = p * 7.0 + 5.0;
165	  float pc = cells(pp);
166	  float kp = 1.0 - smoothstep(0.1, 0.25, fw * 7.0);
167	  col = mix(col, vec3(0.58, 0.56, 0.88), (1.0 - smoothstep(0.1, 0.2, pc)) * step(0.62, hash12(floor(pp))) * 0.75 * kp);
168	  #endif
169	  float spec = pow(max(dot(reflect(-V, N), L), 0.0), 28.0);
170	  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.0);
171	  col += vec3(1.0) * spec * 0.45 + iridescent(fres * 1.4 + c1 * 0.6) * fres * 0.18;
172	  col *= 0.96;
173	  // 05 (wave 7): the low rim under the puffs reads as small piled soap bubbles: white only on the cell
174	  // tops, periwinkle bodies, blue-violet crevices between the cells (ref 05 rim)
175	  float k05 = smoothstep(uSt05.x, uSt05.y, s) * (1.0 - smoothstep(uSt05.z, uSt05.w, s));
176	  // 05: the bank stops just past its bubble crest with a scalloped (cell) edge, so the purple wall shows right above
177	  // the rim instead of a pale lather slope (ref 05; e is the raw offset outward from the stream edge)
178	  if (vFoam.x > mix(9.0, 0.3 + 0.45 * (1.0 - c1), k05)) discard;
179	  if (k05 > 0.0) {
180	    vec3 Nv = normalize((viewMatrix * vec4(N, 0.0)).xyz);
181	    float t5 = soapT(Nv) * 0.55 + 0.45 * mix(0.55, bub, max(k1, 0.3)) - 0.1;
182	    t5 -= smoothstep(0.55, 0.95, c1) * 0.45 * k1 + smoothstep(0.62, 0.95, c2) * 0.25 * k2;
183	    vec3 c5 = soap05(t5);
184	    #ifndef LOW_Q
185	    c5 = mix(c5, SOAP_CREV, (1.0 - smoothstep(0.1, 0.2, pc)) * step(0.62, hash12(floor(pp))) * 0.7 * kp);
186	    #endif
187	    c5 += vec3(1.0) * spec * 0.3;
188	    col = mix(col, c5, k05);
189	  }
190	  gl_FragColor = vec4(col, 1.0);
191	  ${FRAG_TAIL}
192	}
193	`;
194	
195	// ---------------------------------------------------------------------------------- puffs
196	/**
197	 * Soap-foam puff (ref 05 "cloud banks": white-lavender clumps, #FCF6FF lit tops, soft lavender
198	 * undersides and crevices, a few darker pores, faint soap-film rim). instanceColor carries
199	 * (x = ambient occlusion 0..1, y = seed, z = tint -1..1), not a colour.
200	 */
201	const PUFF_VERT = /* glsl */ `
202	uniform float uTime;
203	varying vec3 vNormalW;
204	varying vec3 vPosW;
205	varying vec3 vLocal;
206	varying vec3 vInst;
207	varying float vW5;
208	#include <fog_pars_vertex>
209	void main() {
210	  // instanceColor.x = ao + 2 q, q = 0..8 = the 05 soap-shading weight x 8 (wave 7; ao <= 1 so floor(x / 2) = q)
211	  float q5 = floor(instanceColor.x * 0.5);
212	  vInst = vec3(instanceColor.x - 2.0 * q5, instanceColor.yz);
213	  vW5 = q5 / 8.0;
214	  float br = 1.0 + 0.035 * sin(uTime * 1.7 + instanceColor.y * 40.0);
215	  vec4 wp = modelMatrix * instanceMatrix * vec4(position * br, 1.0);
216	  vPosW = wp.xyz;
217	  vNormalW = normalize(mat3(modelMatrix) * mat3(instanceMatrix) * normal);
218	  vLocal = normal;
219	  vec4 mvPosition = viewMatrix * wp;
220	  gl_Position = projectionMatrix * mvPosition;
221	  #include <fog_vertex>
222	}
223	`;
224	const PUFF_FRAG = /* glsl */ `
225	uniform vec3 uLightDir;
226	varying vec3 vNormalW;
227	varying vec3 vPosW;
228	varying vec3 vLocal;
229	varying vec3 vInst;
230	varying float vW5;
231	#include <fog_pars_fragment>
232	${NOISE_GLSL}
233	${SOAP05_GLSL}
234	void main() {
235	  vec3 N = normalize(vNormalW);
236	  vec3 V = normalize(cameraPosition - vPosW);
237	  vec3 L = normalize(uLightDir);
238	  float wrap = clamp(dot(N, L) * 0.55 + 0.5, 0.0, 1.0);
239	  float upF = clamp(N.y * 0.5 + 0.5, 0.0, 1.0);
240	  float lit = smoothstep(0.18, 0.88, wrap * 0.65 + upF * 0.35);
241	  vec3 c5 = vec3(0.0);
242	  if (vW5 > 0.0) {
243	    // 05 (wave 7): ref soap ramp, view-space top light: white caps, periwinkle bodies, blue crevice rims
244	    vec3 Nv = normalize((viewMatrix * vec4(N, 0.0)).xyz);
245	    float z = clamp(Nv.z, 0.0, 1.0);
246	    float t5 = soapT(Nv) - pow(1.0 - z, 1.5) * (0.3 + 0.45 * clamp(0.5 - Nv.y * 0.7, 0.0, 1.0)) - (1.0 - vInst.x) * 0.35;
247	    c5 = soap05(t5 + 0.04 * vInst.z);
248	    #ifndef LOW_Q
249	    vec3 an5 = abs(vLocal);
250	    vec2 pc5 = (an5.x > an5.z ? vLocal.zy : vLocal.xy) * 2.6 + vInst.y * 17.0;
251	    float kp5 = 1.0 - smoothstep(0.2, 0.45, fwidth(pc5.x) + fwidth(pc5.y));
252	    c5 = mix(c5, SOAP_CREV, (1.0 - smoothstep(0.1, 0.2, cells(pc5))) * step(0.6, hash12(floor(pc5) + vInst.y * 31.0)) * kp5 * 0.5);
253	    #endif
254	    c5 += vec3(1.0) * pow(max(dot(reflect(-V, N), L), 0.0), 26.0) * 0.25;
255	  }
256	  vec3 lav = vec3(0.47, 0.44, 0.88);
257	  vec3 top = mix(vec3(1.1, 1.04, 1.16), vec3(1.04, 1.06, 1.16), clamp(vInst.z, 0.0, 1.0));
258	  top = mix(top, vec3(1.12, 1.02, 1.12), clamp(-vInst.z, 0.0, 1.0));
259	  vec3 col = mix(lav, top, lit);
260	  #ifndef LOW_Q
261	  // pores: small open bubbles on the puff skin (puff-local, two planar projections, no seam)
262	  vec3 an = abs(vLocal);
263	  vec2 pc = (an.x > an.z ? vLocal.zy : vLocal.xy) * 2.6 + vInst.y * 17.0;
264	  float cp = cells(pc);
265	  float kp = 1.0 - smoothstep(0.2, 0.45, fwidth(pc.x) + fwidth(pc.y));
266	  float pore = (1.0 - smoothstep(0.1, 0.2, cp)) * step(0.6, hash12(floor(pc) + vInst.y * 31.0));
267	  col = mix(col, lav * 0.95, pore * kp * 0.6 * lit);
268	  #endif
269	  // soap-film rim (cool lavender, a touch of pink) + soft glint
270	  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 2.4);
271	  col = mix(col, vec3(0.8, 0.68, 1.0), fres * 0.42);
272	  float spec = pow(max(dot(reflect(-V, N), L), 0.0), 26.0);
273	  col += vec3(1.0) * spec * 0.3;
274	  col *= mix(0.68, 1.0, vInst.x);
275	  col = mix(col, c5, vW5);
276	  gl_FragColor = vec4(col, 1.0);
277	  ${FRAG_TAIL}
278	}
279	`;
280	
281	function rng(seed: number) {
282	  let a = seed >>> 0;
283	  return () => {
284	    a = (a + 0x6d2b79f5) >>> 0;
285	    let t = a;
286	    t = Math.imul(t ^ (t >>> 15), t | 1);
287	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
288	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
289	  };
290	}
291	
292	function makePuffMaterial(quality: 'high' | 'low') {
293	  const uniforms = withFog({
294	    uTime: { value: 0 },
295	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
296	  });
297	  const mat = new THREE.ShaderMaterial({
298	    uniforms,
299	    vertexShader: PUFF_VERT,
300	    fragmentShader: PUFF_FRAG,
301	    fog: true,
302	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
303	  });
304	  return { mat, uniforms };
305	}
306	
307	/**
308	 * 05 flank-bank bubble: a camera-facing sphere IMPOSTOR (2 triangles) shaded like the soap puffs
309	 * (white-lavender lit top, lavender underside, soap-film rim that reads as the crevice between piled
310	 * bubbles, a few pores, a glint). instanceColor = (ambient occlusion, seed, tint) as for the puffs.
311	 * The quad is pushed to the sphere's front so the lather apron and neighbours cut it like a sphere.
312	 */
313	const BANK_BUB_VERT = /* glsl */ `
314	varying vec2 vP;
315	varying vec3 vInst;
316	varying float vBig;
317	#include <fog_pars_vertex>
318	void main() {
319	  vec4 c = modelMatrix * instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0);
320	  float r = length((instanceMatrix * vec4(1.0, 0.0, 0.0, 0.0)).xyz);
321	  vec4 mvPosition = viewMatrix * c;
322	  // wave 7: 0 for bubbles <= ~18 px, 1 for >= ~40 px on screen (the ref's big near bumps show large white caps)
323	  vBig = smoothstep(0.012, 0.026, projectionMatrix[1][1] * r / max(-mvPosition.z, 0.01));
324	  mvPosition.xyz += normalize(-mvPosition.xyz) * r * 0.6;
325	  mvPosition.xy += position.xy * r;
326	  vP = position.xy;
327	  vInst = instanceColor;
328	  gl_Position = projectionMatrix * mvPosition;
329	  #include <fog_vertex>
330	}
331	`;
332	const BANK_BUB_FRAG = /* glsl */ `
333	uniform vec3 uLightDir;
334	uniform float uTime;
335	varying vec2 vP;
336	varying vec3 vInst;
337	varying float vBig;
338	#include <fog_pars_fragment>
339	${NOISE_GLSL}
340	${SOAP05_GLSL}
341	void main() {
342	  float d2 = dot(vP, vP);
343	  if (d2 > 1.0) discard;
344	  float z = sqrt(1.0 - d2);
345	  vec3 Nv = vec3(vP, z);
346	  // wave 7: ref 05 soap ramp (white top caps, lavender-white bodies, periwinkle / blue undersides); the
347	  // lower and side silhouette sinks into blue-violet (the crevice between piled bubbles), the top edge stays
348	  // light; inner / lower bubbles of a pile (ambient occlusion vInst.x) are bluer
349	  float t = soapT(Nv) - pow(1.0 - z, 1.5) * (0.3 + 0.45 * clamp(0.5 - vP.y * 0.7, 0.0, 1.0)) - (1.0 - vInst.x) * 0.35 + 0.05 * vBig;
350	  vec3 col = soap05(t + 0.04 * vInst.z);
351	  // pores: one or two small dark-blue open bubbles on the larger puffs
352	  vec2 pc = vP * 2.2 + vInst.y * 17.0;
353	  float cp = cells(pc);
354	  float kp = 1.0 - smoothstep(0.25, 0.5, fwidth(pc.x) * 2.0);
355	  col = mix(col, SOAP_CREV, (1.0 - smoothstep(0.1, 0.2, cp)) * step(0.7, hash12(floor(pc) + vInst.y * 31.0)) * kp * 0.5);
356	  vec3 Lv = (viewMatrix * vec4(normalize(uLightDir), 0.0)).xyz;
357	  float spec = pow(max(dot(reflect(vec3(0.0, 0.0, -1.0), Nv), Lv), 0.0), 24.0);
358	  col += vec3(1.0) * spec * 0.25;
359	  gl_FragColor = vec4(col, 1.0);
360	  ${FRAG_TAIL}
361	}
362	`;
