373	/** unit sphere puff with smooth normals (detail 0 icosahedra get flat normals by default) */
374	function puffGeometry(detail: number) {
375	  const g = new THREE.IcosahedronGeometry(1, detail);
376	  const p = g.attributes.position as THREE.BufferAttribute;
377	  const n = g.attributes.normal as THREE.BufferAttribute;
378	  const v = new THREE.Vector3();
379	  for (let i = 0; i < p.count; i++) { v.fromBufferAttribute(p, i).normalize(); n.setXYZ(i, v.x, v.y, v.z); }
380	  return g;
