394	  update(time: number, dt: number, focusS: number, outro?: number, camera?: THREE.Camera): void;
395	  /** QA: current flank-bank placement (kind L/R, row ds, inner-edge lateral, bank width) */
396	  qaRafts(): { visible: boolean; puffs: number; shown: number; clumps: { kind: string; ds: number; lat: number; k: number; y?: number; x?: number; env?: number; s?: number }[] };
