400	// ---------------------------------------------------------------------------------- flank banks (05)
401	/**
402	 * In 05 the stream fills the tube floor wall to wall (S05.extent), so from the locked chase camera the
403	 * real stream edges and their berm leave the frame below y≈800 and the near field shows only open water.
404	 * Ref 05 has white cloud banks hugging BOTH sides all the way down to Benny's level (left x≈0–330 over
405	 * y≈540–1300, right x≈560–864). Wave 4: one continuous bank per side, fitted to the frame edges each
406	 * frame from the camera (so it holds for any device aspect), not floating islands:
407	 *  - a lather sheet (berm shader) from just below the frame bottom (ds −3.4) up the side of the frame
408	 *    until it merges into the berm (ds +15); its inner edge sits BANK_PX px in from the frame edge
409	 *    (lumpy, slow noise along s) and dips just under the water so the stream cuts a natural waterline;
410	 *  - instanced puffs (rim, crest, heaps) anchored to world cells along s, so the bank stays put on the
411	 *    water like the berm and Benny rides past it; they give the lumpy cloud silhouette.
412	 * Never closer than BANK_CLEAR_RIDER to Benny (near him) or BANK_CLEAR_CORE to the cyan core / coin line.
413	 */
414	const BANK_DS0 = -3.4;
415	const BANK_DS1 = 15;
416	/** puffs stop here (further ahead the berm and its own puffs take over) */
417	const BANK_PUFF_DS1 = 12.5;
418	/** inner edge of a clump at its widest: px in from the frame edge (of an 864-px wide frame), L / R */
419	const BANK_PX: [number, number] = [170, 200];
420	/** lateral size of a clump (px): a clump whose inner edge lies further in than this floats off the frame
421	 * edge with water beyond it (ref 05 lower clumps x≈50–200 and 610–790) */
422	const CLUMP_PX = 135;
423	/**
424	 * The flank lather SHEET (berm shader) read as flat white paper with straight cut edges at the clump ends;
425	 * the ref clumps are piled bubbles only, so wave 5 hides it and the impostor bubbles carry the clumps.
426	 */
427	const FLANK_SHEET = false;
428	/**
429	 * Wave 5: world-anchored clump envelope per side, [seed, frequency along s, threshold]. The near-field bank is a
430	 * chain of separate LOW clumps with open water between them (ref 05: left clumps y≈1016–1108 and
431	 * 1202–1330, right y≈800–950 and 1217–1300), not a continuous strip up the frame edge (wave 4 read as
432	 * a white wall: the outer 40 px were foam on 74 % / 100 % of the rows y 700–1400). The seeds put the
433	 * clumps of the QA frame (s≈132.4) where the ref has them; along 05 clumps cover ≈40 % of the length.
434	 */
435	const BANK_ENV: [number, number, number][] = [[58.457, 0.835, 0.581], [607.242, 0.459, 0.357], [267.601, 1.094, 0.563]];
436	/**
437	 * wave 7 (ref 05 rows, qa/pilot05/wave7/foam): the bank row's inner edge (px in from the frame edge) and lateral size
438	 * (px) by row ds. The right bank ahead of Benny is a NARROW rim hugging the river edge (ref y 700-940: inner edge
439	 * 30 -> 158 -> 70 px, 20-66 px per row), not the wave-5 heap (124-179 px per row). The ref's near clumps: left x 0-130
440	 * y 1020-1110 (ds 0.5-1.5), lower left x 60-230 y 1220-1300 and lower right x 650-800 y 1260-1330 (behind Benny,
441	 * ds -1.1..-1.7). The envelope seeds
442	 * (BANK_ENV, searched; [2] = right side beside / behind Benny) open/close the clumps at those rows of the QA frame.
443	 */
444	const RIM_R: [number, number][] = [[2.6, 60], [3.4, 70], [4.4, 105], [5.5, 140], [6.6, 158], [7.8, 153], [9.0, 135], [10.3, 104], [11.6, 70], [12.9, 30]];
445	const RIM_R_PX = 80;
446	function rimR(ds: number): number {
447	  if (ds <= RIM_R[0][0]) return RIM_R[0][1];
448	  for (let i = 1; i < RIM_R.length; i++) {
449	    if (ds <= RIM_R[i][0]) {
450	      const [a, pa] = RIM_R[i - 1], [b, pb] = RIM_R[i];
451	      return pa + ((pb - pa) * (ds - a)) / (b - a);
452	    }
453	  }
454	  return RIM_R[RIM_R.length - 1][1];
455	}
456	const BANK_CLEAR_RIDER = 1.3;
457	const BANK_CLEAR_CORE = 1.45;
458	
459	/**
460	 * wave 5: 0.4 in 05 (smooth ramps at the stage ends), 1 elsewhere. In 05 the stream-edge rim toward the VP
461	 * is a LOW band of piled bubbles (ref ≈40–60 px); the full-height berm read as tall white heaps.
462	 */
463	function bermScale05(course: Course): (s: number) => number {
464	  const st = course.stage('05');
465	  const sm = (a: number, b: number, x: number) => { const u = Math.min(1, Math.max(0, (x - a) / (b - a))); return u * u * (3 - 2 * u); };
466	  return (s) => 1 - 0.6 * sm(st.s0 - 6, st.s0 - 1, s) * (1 - sm(st.s1 - 1, st.s1 + 4, s));
467	}
468	/** squash the part of the bank above the stream's edge water level by k (k = 1: unchanged) */
469	const squashBerm = (h: number, k: number) => (k < 1 && h > EDGE_LIFT ? EDGE_LIFT + (h - EDGE_LIFT) * k : h);
470	
471	/** continuous lather bank along both stream edges (skips the 03 whirlpool interior) */
472	function createBerm(course: Course, s0: number, s1: number, skip: [number, number], quality: 'high' | 'low') {
473	  const hk = bermScale05(course);
474	  const ds = quality === 'high' ? 0.32 : 0.8;
475	  const E = quality === 'high' ? [BERM_IN, -0.4, -0.25, -0.1, 0.04, 0.18, 0.34, 0.52, 0.75, 0.98, BERM_OUT] : [BERM_IN, -0.2, 0.15, 0.55, BERM_OUT];
476	  const rows = Math.ceil((s1 - s0) / ds) + 1;
477	  const C = E.length;
478	  const n = rows * C * 2;
479	  const pos = new Float32Array(n * 3);
480	  const foam = new Float32Array(n * 3);
481	  const tmp = new THREE.Vector3();
482	  let k = 0;
483	  const rowS: number[] = [];
484	  for (let i = 0; i < rows; i++) {
485	    const s = Math.min(s1, s0 + i * ds);
486	    rowS.push(s);
487	    const f = course.sample(s);
488	    const hw = course.widthAt(s) / 2;
489	    for (const side of [-1, 1]) {
490	      for (let j = 0; j < C; j++) {
491	        // left side is mirrored so every row runs inner → outer; bubble domes everywhere except
492	        // at the water line (keeps the lace edge flush with the stream)
493	        const e = E[j];
494	        const k05 = hk(s);
495	        const h = squashBerm(bermSurface(s, e, side, hw), k05);
496	        // 05: the outer (dry) side is laterally compressed too, so the rim is a narrow band of bubbles
497	        const eS = e > 0 ? e * (0.1 + 0.9 * k05) : e;
498	        tmp.copy(f.pos).addScaledVector(f.right, side * (hw + eS)).addScaledVector(f.up, h);
499	        tmp.toArray(pos, k * 3);
500	        foam[k * 3] = e;
501	        foam[k * 3 + 1] = s;
502	        foam[k * 3 + 2] = side;
503	        k++;
504	      }
505	    }
506	  }
507	  const idx: number[] = [];
508	  const rowStride = C * 2;
509	  for (let i = 0; i < rows - 1; i++) {
510	    const sa = rowS[i], sb = rowS[i + 1];
511	    if (sb > skip[0] && sa < skip[1]) continue;
512	    for (let sideI = 0; sideI < 2; sideI++) {
513	      for (let j = 0; j < C - 1; j++) {
514	        const a = i * rowStride + sideI * C + j, b = a + 1, c = a + rowStride, d = c + 1;
515	        // CCW seen from above on both sides (side +1 runs +right, side −1 runs −right)
516	        if (sideI === 1) idx.push(a, b, c, b, d, c);
517	        else idx.push(a, c, b, b, c, d);
518	      }
519	    }
520	  }
521	  const geo = new THREE.BufferGeometry();
522	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
523	  geo.setAttribute('aFoam', new THREE.BufferAttribute(foam, 3));
524	  geo.setIndex(idx);
525	  geo.computeVertexNormals();
526	  const st05 = course.stage('05');
527	  const uniforms = withFog({
528	    uTime: { value: 0 },
529	    uOutro: { value: new THREE.Vector2(0, course.stage('08').s0) },
530	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
531	    // colour starts at the 05 stage start (not s0 - 6 like the squash) so the 04 frame keeps its own foam colours
532	    uSt05: { value: new THREE.Vector4(st05.s0 - 1, st05.s0 + 2, st05.s1 - 1, st05.s1 + 4) },
533	  });
534	  const mat = new THREE.ShaderMaterial({
535	    uniforms,
536	    vertexShader: BERM_VERT,
537	    fragmentShader: BERM_FRAG,
538	    fog: true,
539	    side: THREE.DoubleSide,
540	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
541	  });
542	  const mesh = new THREE.Mesh(geo, mat);
543	  mesh.name = 'foam_berm';
544	  mesh.frustumCulled = false;
545	  return { mesh, uniforms };
546	}
