548	export function createFoam(
549	  course: Course,
550	  opts: { s0: number; s1: number; quality: 'high' | 'low'; height?: (s: number, lat: number, t: number) => number },
551	): FoamSystem {
552	  const { s0, s1, quality } = opts;
553	  const heightAt = opts.height ?? (() => 0);
554	  const rand = rng(1337);
555	  const density = quality === 'high' ? 1 : 0.5;
556	  // LOD: 80-tri puffs in the chunks around Benny, 20-tri puffs further out (low tier: 20-tri only)
557	  const geoHi = puffGeometry(quality === 'high' ? 1 : 0);
558	  const geoLo = quality === 'high' ? puffGeometry(0) : geoHi;
559	  const puff = makePuffMaterial(quality);
560	  const mat = puff.mat;
561	  const group = new THREE.Group();
562	  group.name = 'foam_banks';
563	  const st03 = course.stage('03'), st04 = course.stage('04');
564	  const chunkLen = 24;
565	  const chunks: { mesh: THREE.InstancedMesh; sa: number; sb: number }[] = [];
566	  let total = 0;
567	  const tmpM = new THREE.Matrix4();
568	  const tmpQ = new THREE.Quaternion();
569	  const tmpS = new THREE.Vector3();
570	  const tmpE = new THREE.Euler();
571	  const tmpC = new THREE.Color();
572	
573	  const build = (list: Puff[], parent: THREE.Object3D, sa: number, sb: number) => {
574	    if (!list.length) return;
575	    const mesh = new THREE.InstancedMesh(geoHi, mat, list.length);
576	    list.forEach((pf, i) => {
577	      tmpQ.setFromEuler(tmpE.set(rand() * 6, rand() * 6, rand() * 6));
578	      tmpS.set(pf.r, pf.r * (0.78 + rand() * 0.22), pf.r);
579	      tmpM.compose(pf.p, tmpQ, tmpS);
580	      mesh.setMatrixAt(i, tmpM);
581	      // x = ao + 2 q (q = 05 soap-shading weight x 8, see PUFF_VERT)
582	      mesh.setColorAt(i, tmpC.setRGB(pf.ao + 2 * Math.round(Math.min(1, Math.max(0, pf.w5 ?? 0)) * 8), rand(), pf.tint));
583	    });
584	    mesh.instanceMatrix.needsUpdate = true;
585	    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
586	    mesh.computeBoundingSphere();
587	    parent.add(mesh);
588	    chunks.push({ mesh, sa, sb });
589	    total += list.length;
590	  };
591	
592	  // ---- continuous lather bank (berm) along both edges ----
593	  const skip: [number, number] = [st03.s0 + 4, st04.s0 - 6];
594	  const berm = createBerm(course, s0, s1, skip, quality);
595	  group.add(berm.mesh);
596	
597	  // ---- cloud banks of puffs hugging both stream edges (ref 05: 10–40 px white-lavender clumps) ----
598	  const inSkip = (s: number) => s > skip[0] && s < skip[1];
599	  // wave 5: in 05 the stream-edge rim toward the VP is a LOW rim of piled bubbles (ref ≈40–60 px), not
600	  // tall heaps: crest puffs × 0.85, heaps × 0.6 and never stacked. Only sizes change, so the shared
601	  // rand() sequence (and every other stage's foam) stays identical.
602	  const st05b = course.stage('05');
603	  const bermK = bermScale05(course);
604	  const low05 = (s: number) => s > st05b.s0 - 4 && s < st05b.s1 + 2;
605	  const addPuff = (list: Puff[], s: number, e: number, side: number, r: number, lift: number, ao: number) => {
606	    const ss = Math.min(s1, Math.max(s0, s));
607	    if (inSkip(ss)) return;
608	    const f = course.sample(ss);
609	    const hw = course.widthAt(ss) / 2;
610	    const k05 = bermK(ss);
611	    const h = squashBerm(bermSurface(ss, e, side, hw), k05) + lift;
612	    const eS = e > 0 ? e * (0.1 + 0.9 * k05) : e;
613	    const p = f.pos.clone().addScaledVector(f.right, side * (hw + eS)).addScaledVector(f.up, h);
614	    list.push({ p, r, ao, tint: rand() * 2 - 1, w5: soap05W(ss) });
615	  };
616	  const smw = (a: number, b: number, x: number) => { const u = Math.min(1, Math.max(0, (x - a) / (b - a))); return u * u * (3 - 2 * u); };
617	  /** 05 soap-shading weight of a puff (same ramp as the berm's uSt05) */
618	  const soap05W = (s: number) => smw(st05b.s0 - 1, st05b.s0 + 2, s) * (1 - smw(st05b.s1 - 1, st05b.s1 + 4, s));
619	  const step = quality === 'high' ? 0.36 : 0.62;
620	  for (let sa = s0; sa < s1; sa += chunkLen) {
621	    const sb = Math.min(s1, sa + chunkLen);
622	    const list: Puff[] = [];
623	    // skip most of 03 (the whirlpool has its own foam), keep the chute→rim hand-over
624	    for (let s = sa; s < sb; s += step) {
625	      if (inSkip(s)) continue;
626	      for (const side of [-1, 1]) {
627	        // crest puffs: the body of the bank
628	        const nC = quality === 'high' && rand() < 0.55 ? 2 : 1;
629	        for (let k = 0; k < nC; k++) {
630	          const r = (0.11 + rand() * 0.13) * (low05(s) ? 0.85 : 1);
631	          addPuff(list, s + (rand() - 0.5) * step, -0.32 + rand() * 0.82, side, r, r * (0.05 + rand() * 0.3), 0.8 + 0.2 * rand());
632	        }
633	        // small puffs right at the water line (the lacy edge of the bank)
634	        if (rand() < 0.65) {
635	          const r = 0.06 + rand() * 0.06;
636	          addPuff(list, s + (rand() - 0.5) * step, -0.58 + rand() * 0.28, side, r, r * 0.15, 0.9);
637	        }
638	      }
639	      // heaps: clusters of big puffs stacked on the crest → lumpy cloud-bank silhouette
640	      if (rand() < (quality === 'high' ? 0.16 : 0.1)) {
641	        const side = rand() < 0.5 ? -1 : 1;
642	        const n = 5 + ((rand() * 6) | 0);
643	        const ec = -0.1 + rand() * 0.55;
644	        const lo = low05(s);
645	        for (let k = 0; k < n; k++) {
646	          const r = (0.15 + rand() * 0.18) * (lo ? 0.6 : 1);
647	          const stack = k > 2 && rand() < 0.4 && !lo ? r * 0.65 : 0;
648	          const lift = r * (0.1 + rand() * 0.45) + stack;
649	          addPuff(list, s + (rand() - 0.5) * 1.8, ec + (rand() - 0.5) * 0.55, side, r, lift, 0.72 + 0.28 * Math.min(1, lift / (r * 0.9)));
650	        }
651	      }
652	    }
653	    build(list, group, sa - 2, sb + 2);
654	  }
655	
656	  // ---- whirlpool: rim ring + spiral band foam (rotates with the swirl) ----
657	  const whirlGroup = new THREE.Group();
658	  whirlGroup.name = 'foam_whirlpool';
659	  const b = WORLD.basin;
660	  whirlGroup.position.set(b.center.x, 0, b.center.z);
661	  const wl: Puff[] = [];
662	  // rim: cloud clusters of soap foam with a thin continuous fringe between them
663	  const nClusters = Math.round(26 * density);
664	  for (let k = 0; k < nClusters; k++) {
665	    const th0 = rand() * Math.PI * 2;
666	    const n = 10 + ((rand() * 16) | 0);
667	    for (let i = 0; i < n; i++) {
668	      const th = th0 + (rand() - 0.5) * 0.35;
669	      const r = b.rimRadius - 0.7 + (rand() - 0.4) * 1.3;
670	      const sz = 0.18 + rand() * 0.42;
671	      wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.35 + rand() * 0.55, r * Math.cos(th)), r: sz, ao: 0.75 + 0.25 * rand(), tint: rand() * 2 - 1 });
672	    }
673	  }
674	  const nRim = Math.round(200 * density);
675	  for (let i = 0; i < nRim; i++) {
676	    const th = rand() * Math.PI * 2;
677	    const r = b.rimRadius - 0.4 + (rand() - 0.5) * 0.6;
678	    const sz = 0.1 + rand() * 0.18;
679	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, ao: 0.85 + 0.15 * rand(), tint: rand() * 2 - 1 });
680	  }
681	  // along 3 spiral flow lines (constant th - C ln r) to echo the white foam bands
682	  const nBand = Math.round(60 * density);
683	  for (let i = 0; i < nBand; i++) {
684	    const band = ((i % 3) * Math.PI * 2) / 3 + 0.4;
685	    const r = 3.0 + rand() * (b.rimRadius - 3.6);
686	    const th = band + SPIRAL_C * Math.log(r) + (rand() - 0.5) * 0.12;
687	    const sz = 0.07 + rand() * 0.13;
688	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, ao: 0.85 + 0.15 * rand(), tint: rand() * 2 - 1 });
689	  }
690	  const whirlStart = chunks.length;
691	  build(wl, whirlGroup, st03.s0 - 30, st04.s0 + 25);
692	  group.add(whirlGroup);
693	
694	  // ---- 05 flank banks: lather sheet + world-anchored bubble puffs fitted to the frame edges ----
695	  const st05 = course.stage('05');
696	  const sm = (a: number, b: number, x: number) => {
697	    const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
698	    return t * t * (3 - 2 * t);
699	  };
700	  const R = quality === 'high' ? 40 : 22; // sheet rows per side
701	  const C = quality === 'high' ? 7 : 5; // sheet columns (inner edge → beyond the frame edge)
702	  const bankPos = new Float32Array(2 * R * C * 3);
703	  const bankFoam = new Float32Array(2 * R * C * 3);
704	  const bankIdx: number[] = [];
705	  for (let sd = 0; sd < 2; sd++) {
706	    for (let i = 0; i < R - 1; i++) {
707	      for (let j = 0; j < C - 1; j++) {
708	        const a = (sd * R + i) * C + j, b = a + 1, c = a + C, d = c + 1;
709	        quadIdx(bankIdx, sd, a, b, c, d);
710	      }
711	    }
712	  }
713	  const bankGeo = new THREE.BufferGeometry();
714	  bankGeo.setAttribute('position', new THREE.BufferAttribute(bankPos, 3).setUsage(THREE.DynamicDrawUsage));
715	  bankGeo.setAttribute('aFoam', new THREE.BufferAttribute(bankFoam, 3).setUsage(THREE.DynamicDrawUsage));
716	  bankGeo.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(2 * R * C * 3), 3).setUsage(THREE.DynamicDrawUsage));
717	  bankGeo.setIndex(bankIdx);
718	  const flank = new THREE.Mesh(bankGeo, berm.mesh.material);
719	  flank.name = 'foam_flank';
720	  flank.frustumCulled = false;
721	  flank.visible = false;
722	  group.add(flank);
